import { createContextId } from "@builder.io/qwik";
import type { Signal } from "@builder.io/qwik";

export type Theme = "light" | "dark";

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

export interface CartStore {
  items: CartItem[];
}

/** Reactive theme value, either "light" or "dark". */
export const ThemeContext = createContextId<Signal<Theme>>(
  "app.theme-context",
);

/** Reactive store holding all cart items. */
export const CartContext = createContextId<CartStore>("app.cart-context");

import {
  component$,
  Slot,
  useContextProvider,
  useSignal,
  useStore,
} from "@builder.io/qwik";
import { CartContext, ThemeContext, type CartStore, type Theme } from "~/context";

export default component$(() => {
  // Reactive theme value, shared through context with every descendant.
  const theme = useSignal<Theme>("light");

  // Reactive cart store, shared through context with every descendant.
  const cart = useStore<CartStore>({
    items: [
      { id: "sku-1", name: "Keyboard", price: 49.99, quantity: 1 },
      { id: "sku-2", name: "Mouse", price: 19.99, quantity: 2 },
    ],
  });

  // Provide both contexts exactly once, at the root route layout.
  useContextProvider(ThemeContext, theme);
  useContextProvider(CartContext, cart);

  return <Slot />;
});

import { component$ } from "@builder.io/qwik";
import type { DocumentHead } from "@builder.io/qwik-city";
import { StorePage } from "~/components/store-page";

// Route component: 1 level below the context provider in routes/layout.tsx.
export default component$(() => {
  return <StorePage />;
});

export const head: DocumentHead = {
  title: "Qwik Context DI Storefront",
  meta: [
    {
      name: "description",
      content: "Shopping cart storefront demo using Qwik context dependency injection",
    },
  ],
};

import { component$ } from "@builder.io/qwik";
import { AppRoot } from "./app-root";

// 2 levels below the context provider.
export const StorePage = component$(() => {
  return <AppRoot />;
});

import { component$, useContext } from "@builder.io/qwik";
import { ThemeContext } from "~/context";
import { ThemeSection } from "./theme-section";
import { CartSection } from "./cart-section";

// 3 levels below the context provider (routes/layout.tsx -> routes/index.tsx
// -> StorePage -> AppRoot). The theme value here is obtained exclusively via
// useContext, never through props.
export const AppRoot = component$(() => {
  const theme = useContext(ThemeContext);

  return (
    <div
      data-testid="app-root"
      data-theme={theme.value}
      class={`app-root theme-${theme.value}`}
    >
      <ThemeSection />
      <CartSection />
    </div>
  );
});

import { component$ } from "@builder.io/qwik";
import { ThemeLabel } from "./theme-label";
import { ThemeToggle } from "./theme-toggle";

// 4 levels below the context provider.
export const ThemeSection = component$(() => {
  return (
    <section class="theme-section">
      <ThemeLabel />
      <ThemeToggle />
    </section>
  );
});

import { component$, useContext } from "@builder.io/qwik";
import { ThemeContext } from "~/context";

// 5 levels below the context provider. Consumes the theme exclusively via
// useContext.
export const ThemeLabel = component$(() => {
  const theme = useContext(ThemeContext);

  return <div data-testid="theme-label">Theme: {theme.value}</div>;
});

import { component$, useContext } from "@builder.io/qwik";
import { ThemeContext } from "~/context";

// 5 levels below the context provider. Mutates the shared theme signal
// directly via useContext, no handler is passed down as a prop.
export const ThemeToggle = component$(() => {
  const theme = useContext(ThemeContext);

  return (
    <button
      data-testid="theme-toggle"
      onClick$={() => {
        theme.value = theme.value === "light" ? "dark" : "light";
      }}
    >
      Toggle Theme
    </button>
  );
});

import { component$ } from "@builder.io/qwik";
import { CartSummary } from "./cart-summary";
import { CartList } from "./cart-list";
import { AddItemButton } from "./add-item-button";

// 4 levels below the context provider.
export const CartSection = component$(() => {
  return (
    <section class="cart-section">
      <CartSummary />
      <CartList />
      <AddItemButton />
    </section>
  );
});

import { component$, useComputed$, useContext } from "@builder.io/qwik";
import { CartContext } from "~/context";

// 5 levels below the context provider. The single useComputed$ in this
// application derives both cart aggregates (count and total price) from the
// injected cart store, obtained exclusively via useContext.
export const CartSummary = component$(() => {
  const cart = useContext(CartContext);

  const aggregates = useComputed$(() => {
    let count = 0;
    let total = 0;

    for (const item of cart.items) {
      count += item.quantity;
      total += item.price * item.quantity;
    }

    return { count, total };
  });

  return (
    <div class="cart-summary">
      <span data-testid="cart-count">{aggregates.value.count}</span>
      <span data-testid="cart-total">${aggregates.value.total.toFixed(2)}</span>
    </div>
  );
});

import { component$, useContext } from "@builder.io/qwik";
import { CartContext } from "~/context";
import { CartItemRow } from "./cart-item-row";

// 5 levels below the context provider. Only plain id strings (never the
// store itself) are passed down to each row component.
export const CartList = component$(() => {
  const cart = useContext(CartContext);

  return (
    <div class="cart-list">
      {cart.items.map((item) => (
        <CartItemRow key={item.id} id={item.id} />
      ))}
    </div>
  );
});

import { component$, useContext } from "@builder.io/qwik";
import { CartContext } from "~/context";

interface CartItemRowProps {
  id: string;
}

// 6 levels below the context provider. Only the plain `id` string is
// received as a prop; the item's reactive data and mutation capability come
// exclusively from useContext.
export const CartItemRow = component$((props: CartItemRowProps) => {
  const cart = useContext(CartContext);
  const item = cart.items.find((i) => i.id === props.id);

  if (!item) {
    return null;
  }

  return (
    <div data-testid={`item-${item.id}`} class="cart-item-row">
      <span class="cart-item-name">{item.name}</span>
      <span data-testid={`qty-${item.id}`}>{item.quantity}</span>
      <button
        data-testid={`dec-${item.id}`}
        onClick$={() => {
          const target = cart.items.find((i) => i.id === props.id);
          if (target && target.quantity > 0) {
            target.quantity -= 1;
          }
        }}
      >
        -
      </button>
      <button
        data-testid={`inc-${item.id}`}
        onClick$={() => {
          const target = cart.items.find((i) => i.id === props.id);
          if (target) {
            target.quantity += 1;
          }
        }}
      >
        +
      </button>
    </div>
  );
});

import { component$, useContext } from "@builder.io/qwik";
import { CartContext } from "~/context";

// 5 levels below the context provider. Mutates the injected cart store
// directly; no handler is lifted to the provider.
export const AddItemButton = component$(() => {
  const cart = useContext(CartContext);

  return (
    <button
      data-testid="add-item"
      onClick$={() => {
        const exists = cart.items.some((item) => item.id === "sku-3");
        if (!exists) {
          cart.items.push({ id: "sku-3", name: "Cable", price: 9.99, quantity: 1 });
        }
      }}
    >
      Add Cable
    </button>
  );
});

body {
  font-family:
    system-ui,
    -apple-system,
    Segoe UI,
    Roboto,
    sans-serif;
  margin: 0;
}

.app-root {
  min-height: 100vh;
  padding: 2rem;
  transition:
    background-color 0.2s ease,
    color 0.2s ease;
}

.app-root.theme-light {
  background-color: #ffffff;
  color: #1a1a1a;
}

.app-root.theme-dark {
  background-color: #1a1a1a;
  color: #f5f5f5;
}

.theme-section,
.cart-section {
  margin-bottom: 1.5rem;
}

.cart-summary {
  display: flex;
  gap: 1.5rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

.cart-item-row {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.5rem 0;
}

.cart-item-name {
  min-width: 8rem;
}

button {
  cursor: pointer;
}
